package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.apache.commons.lang3.text.translate.CharSequenceTranslator;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CharSequenceTranslator_with_TriageGen0Test {

    /**
     * Mock implementation of CharSequenceTranslator to test the 'with' logic.
     */
    private static class TestTranslator extends CharSequenceTranslator {
        private final String replacement;

        TestTranslator(String replacement) {
            this.replacement = replacement;
        }

        @Override
        public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
            out.write(replacement);
            return replacement.length();
        }
    }

    @Test
    public void testWith_SingleTranslator() {
        CharSequenceTranslator base = new TestTranslator("BASE");
        CharSequenceTranslator extra = new TestTranslator("EXTRA");

        CharSequenceTranslator result = base.with(extra);

        assertNotNull(result);
        // Verify the behavior: AggregateTranslator should apply base then extra
        // Based on the implementation, newArray[0] = this, then others follow.
        StringWriter sw = new StringWriter();
        try {
            result.translate("test", sw);
        } catch (IOException e) {
            fail("IOException should not be thrown");
        }

        // The aggregate translator applies translators in order. 
        // Since base is at index 0, it should process the input.
        // Note: The exact behavior depends on how AggregateTranslator calls the translators.
        // But we are testing the 'with' method's ability to construct the array correctly.
        assertTrue(sw.toString().contains("BASE"));
        assertTrue(sw.toString().contains("EXTRA"));
    }

    @Test
    public void testWith_MultipleTranslators() {
        CharSequenceTranslator base = new TestTranslator("BASE");
        CharSequenceTranslator t1 = new TestTranslator("1");
        CharSequenceTranslator t2 = new TestTranslator("2");
        CharSequenceTranslator t3 = new TestTranslator("3");

        CharSequenceTranslator result = base.with(t1, t2, t3);

        assertNotNull(result);
        StringWriter sw = new StringWriter();
        try {
            result.translate("test", sw);
        } catch (IOException e) {
            fail("IOException should not be thrown");
        }

        String output = sw.toString();
        assertTrue(output.contains("BASE"));
        assertTrue(output.contains("1"));
        assertTrue(output.contains("2"));
        assertTrue(output.contains("3"));
    }

    @Test
    public void testWith_EmptyArray() {
        CharSequenceTranslator base = new TestTranslator("BASE");

        // Testing with zero arguments (varargs empty)
        CharSequenceTranslator result = base.with();

        assertNotNull(result);
        StringWriter sw = new StringWriter();
        try {
            result.translate("test", sw);
        } catch (IOException e) {
            fail("IOException should not be thrown");
        }

        // Should only contain the base translator's effect
        assertEquals("BASE", sw.toString());
    }

    @Test
    public void testWith_NullArgument() {
        // Note: Passing null to a varargs parameter results in a null array, 
        // which will cause a NullPointerException in the method when accessing length.
        CharSequenceTranslator base = new TestTranslator("BASE");

        try {
            base.with(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Success
        }
    }
}
